import Card from "@/core/components/primitives/card/card";
import styles from "./save-to-album.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import TextAndLineDivider from "@/core/components/primitives/text-and-line-divider/text-and-line-divider";
import { IDigitalRideMediaService } from "@/core/services/digital-ride-media-service";
import { AnimatePresence, motion } from "framer-motion";
import { useLocalStorage } from "@/core/hooks";
import { useQueries } from "@tanstack/react-query";
import { ExistingAlbumsList } from "../existing-albums-list/existing-albums-list";
import { SearchAlbumForm } from "../search-album-form/search-album-form";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";
import { useTranslation } from "react-i18next";
import { BackButton } from "../back-button/back-button";
import Banner from "@/core/components/primitives/banner/banner";
import { DateHelper } from "@/core/helpers";
import { isAlbumUnlocked } from "../../helpers";

type Props = {
  wrappingElement: "div" | "card";
  service: IDigitalRideMediaService;
  isVisible: boolean;
  /** Date of visit. All media in an album must be of this date. */
  visitDate: string;
  createNewAlbum: () => void;
  addToExistingAlbum: (albumId: string) => void;
  isLoadingCreateAlbum: boolean;
  isLoadingSaveToExistingAlbumId: string | undefined;
  isErrorOnSaveToExistingAlbumId: string | undefined;
  createNewAlbumError: Error | null;
  goBack?: () => void;
  qrCodeAccountMediaNumber?: number;
};

export const SaveToAlbum = ({
  wrappingElement,
  service,
  isVisible,
  createNewAlbum,
  addToExistingAlbum,
  visitDate,
  isLoadingCreateAlbum,
  isLoadingSaveToExistingAlbumId,
  isErrorOnSaveToExistingAlbumId,
  createNewAlbumError,
  goBack,
  qrCodeAccountMediaNumber,
}: Props) => {
  const [savedAlbumsIds] = useLocalStorage<Array<string>>("savedRideMediaAlbumIds", []);

  const albumsMetadataQueries = useQueries({
    queries: savedAlbumsIds.map((albumId) => {
      // eslint-disable-next-line @tanstack/query/exhaustive-deps
      return {
        queryKey: ["album-metadata", albumId],
        queryFn: () => service.fetchAlbum(albumId),
      };
    }),
  });

  const formattedVisitDate = DateHelper.toStringDDMonth(visitDate);
  const visitDateAlbums = savedAlbumsIds
    .map((id, index) => ({ id, query: albumsMetadataQueries[index] }))
    .filter(({ query }) => {
      const albumVisitDate = query.data?.item?.visitDate;
      return !!albumVisitDate && DateHelper.isEqualYYYYMMDD(albumVisitDate, visitDate);
    })
    // Sort so that unlocked albums are shown first
    .sort(({ query: a }, { query: b }) => {
      return Number(isAlbumUnlocked(b.data?.item)) - Number(isAlbumUnlocked(a.data?.item));
    });

  const { t } = useTranslation();

  const imagesToSave = qrCodeAccountMediaNumber || 1;

  return (
    <AnimatePresence>
      {isVisible && (
        <WrappingElement wrappingElement={wrappingElement}>
          {goBack && (
            <div className={styles.topBar}>
              <BackButton onClick={goBack} />
            </div>
          )}
          <h3>{t("rideMediaSaveToAlbumCardHeading")}</h3>
          <div className={styles.saveToAlbumWrapper}>
            {visitDateAlbums.length > 0 && (
              <>
                <h4>{t("rideMediaSaveToAlbumCardExistingAlbumsHeading", { visitDate: formattedVisitDate })}</h4>
                <ExistingAlbumsList
                  albums={visitDateAlbums}
                  action="ADD_TO_ALBUM"
                  albumIdInLoadingState={isLoadingSaveToExistingAlbumId}
                  albumIdInErrorState={isErrorOnSaveToExistingAlbumId}
                  onClick={addToExistingAlbum}
                  addToAlbumMediaAmount={imagesToSave}
                  visitDate={visitDate}
                />
                <TextAndLineDivider text={t("orDivider")} data-testid="digital-ride-media-save-to-album-or-divider" />
                <ExpandContent
                  buttonType="ghost"
                  showMoreLabelOverride={t("rideMediaSaveToAlbumCardShowMoreOptions")}
                  showLessLabelOverride={t("rideMediaSaveToAlbumCardShowLessOptions")}
                >
                  <OtherSavingOptions
                    isLoadingCreateAlbum={isLoadingCreateAlbum}
                    createNewAlbum={createNewAlbum}
                    service={service}
                    albumIdInLoadingState={isLoadingSaveToExistingAlbumId}
                    albumIdInErrorState={isErrorOnSaveToExistingAlbumId}
                    addToExistingAlbum={addToExistingAlbum}
                    createNewAlbumError={createNewAlbumError}
                    imagesToSave={imagesToSave}
                    visitDate={visitDate}
                  />
                </ExpandContent>
              </>
            )}
            {visitDateAlbums.length === 0 && (
              <OtherSavingOptions
                isLoadingCreateAlbum={isLoadingCreateAlbum}
                createNewAlbum={createNewAlbum}
                service={service}
                albumIdInLoadingState={isLoadingSaveToExistingAlbumId}
                albumIdInErrorState={isErrorOnSaveToExistingAlbumId}
                visitDate={visitDate}
                addToExistingAlbum={addToExistingAlbum}
                createNewAlbumError={createNewAlbumError}
                imagesToSave={imagesToSave}
              />
            )}
          </div>
        </WrappingElement>
      )}
    </AnimatePresence>
  );
};

const WrappingElement = ({
  wrappingElement,
  children,
}: {
  wrappingElement: Props["wrappingElement"];
  children: React.ReactNode;
}) => {
  if (wrappingElement === "div") {
    return (
      <motion.div
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        initial={{ opacity: 0 }}
        transition={{ duration: 0.2 }}
      >
        {children}
      </motion.div>
    );
  }
  if (wrappingElement === "card") {
    return (
      <Card
        className={styles.card}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        initial={{ opacity: 0 }}
        transition={{ duration: 0.2 }}
      >
        {children}
      </Card>
    );
  }
  return null;
};

const OtherSavingOptions = ({
  isLoadingCreateAlbum,
  createNewAlbum,
  service,
  addToExistingAlbum,
  createNewAlbumError,
  albumIdInLoadingState,
  albumIdInErrorState,
  imagesToSave,
  visitDate,
}: {
  isLoadingCreateAlbum: boolean;
  createNewAlbum: () => void;
  service: IDigitalRideMediaService;
  addToExistingAlbum: (albumId: string) => void;
  createNewAlbumError: Error | null;
  albumIdInLoadingState: string | undefined;
  albumIdInErrorState: string | undefined;
  imagesToSave: number;
  visitDate: string;
}) => {
  const { t } = useTranslation();
  return (
    <div className={styles.otherSavingOptions} data-testid="digital-ride-media-save-to-album-other-saving-options">
      <p>{t("rideMediaSaveToAlbumCardParagraph")}</p>
      <PrimaryButton
        label={
          isLoadingCreateAlbum
            ? t("rideMediaSaveToAlbumCardCreateNewAlbumButtonLoading")
            : t("rideMediaSaveToAlbumCardCreateNewAlbumButtonStandard")
        }
        iconLeftNew={isLoadingCreateAlbum ? "loading" : "add"}
        isFullWidth
        onClick={createNewAlbum}
        data-testid={
          isLoadingCreateAlbum
            ? "digital-ride-media-save-to-album-create-new-album-button-loading"
            : "digital-ride-media-save-to-album-create-new-album-button"
        }
      />
      {createNewAlbumError && (
        <Banner
          type="critical"
          heading={t("rideMediaSaveToAlbumErrorHeading")}
          paragraph={t("rideMediaSaveToAlbumErrorParagraph")}
        />
      )}
      <TextAndLineDivider text={t("orDivider")} />
      <h4>{t("rideMediaSaveToAlbumCardSearchAlbumHeading")}</h4>
      <p>{t("rideMediaSaveToAlbumCardSearchAlbumParagraph", { count: imagesToSave })}</p>
      <SearchAlbumForm
        service={service}
        albumAction={{ action: "ADD_TO_ALBUM", visitDate }}
        onClickAlbumResult={addToExistingAlbum}
        albumIdInLoadingState={albumIdInLoadingState}
        albumIdInErrorState={albumIdInErrorState}
        addToAlbumMediaAmount={imagesToSave}
      />
    </div>
  );
};
